window.piHealth = function () {
  var month = monthVal();
  var box = document.getElementById('pi-health');
  if (!box) return Promise.resolve();
  var bks = (typeof S !== 'undefined' && Array.isArray(S.bks)) ? S.bks : [];
  if (!bks.length) {
    box.innerHTML = '<b>Hosthub</b> — no bookings loaded. Sync Hosthub on the Dashboard first, then refresh expect.';
    PI.health = { airInv: 0, airCredit: 0, bdcExpect: 0, bdcBookings: 0, bdcApts: [] };
    piRenderBdcChecklist('pi-bdc-expect-list');
    piRenderBdcChecklist('pi-bdc-checklist');
    piFillBdcAptSelect();
    return Promise.resolve();
  }
  var airInv = 0, airCredit = 0, bdcBookings = 0;
  var bdcMap = {};
  var bdcBookMonth = piPrevMonth(month);
  bks.forEach(function (b) {
    var ch = piChan(b);
    var createdYm = piYmFromTs(b.createdOnChannel != null ? b.createdOnChannel : b.created);
    var cancelYm = piYmFromTs(b.cancelledAt);
    if (ch === 'airbnb' && createdYm === month) airInv++;
    if (ch === 'airbnb' && b.cancelled && cancelYm === month) airCredit++;
    if (ch === 'booking' && createdYm === bdcBookMonth && !b.cancelled) {
      bdcBookings++;
      var key = piAptKey(b) || ('unk:' + String(b.id || b.reservationId || b.bookingId || ''));
      if (!bdcMap[key]) {
        bdcMap[key] = {
          aptId: String(b.aptId || b.apartmentId || '').trim(),
          aptName: String(b.aptName || b.apartmentName || '').trim(),
          bookings: 0
        };
      }
      bdcMap[key].bookings++;
    }
  });
  var bdcApts = Object.keys(bdcMap).map(function (k) { return bdcMap[k]; }).sort(function (a, b) {
    return String(a.aptName || a.aptId).localeCompare(String(b.aptName || b.aptId));
  });
  var bdcExpect = bdcApts.length;
  PI.health = {
    airInv: airInv, airCredit: airCredit, bdcExpect: bdcExpect,
    bdcBookings: bdcBookings, bdcBookMonth: bdcBookMonth, bdcApts: bdcApts
  };
  box.innerHTML =
    '<div>Document month <code>' + month + '</code></div>' +
    '<div style="margin-top:6px"><b>Airbnb VAT invoices</b> (created): <b>' + airInv + '</b></div>' +
    '<div style="margin-top:4px"><b>Airbnb credit notes</b> (cancelledAt): <b>' + airCredit + '</b></div>' +
    '<div style="margin-top:4px"><b>Booking.com</b> (stays in <code>' + bdcBookMonth + '</code>): <b>' + bdcExpect + '</b> apartment invoice(s) expected' +
    ' <span style="color:var(--tx3)">(' + bdcBookings + ' booking(s) across those apartments)</span></div>' +
    '<div style="margin-top:8px;color:var(--tx3);font-size:11.5px">Booking.com issues <b>one invoice per apartment</b>. Airbnb: confirm≠cancel months → invoice in one month and credit note in the other.</div>';
  piFillBdcAptSelect();
  return fetch('/api/platform-invoices?month=' + encodeURIComponent(month)).then(function (r) { return r.json(); }).then(function (j) {
    if (!j || !j.ok) {
      piRenderBdcChecklist('pi-bdc-expect-list');
      piRenderBdcChecklist('pi-bdc-checklist');
      return;
    }
    var items = j.items || [];
    PI.items = items;
    var cov = piBdcAptCoverage(items);
    var have = cov.filter(function (x) { return x.have; }).length;
    box.innerHTML += '<div style="margin-top:8px">Already in vault: <b>' + items.length + '</b> file(s)' +
      (bdcExpect ? (' · Booking apartments covered <b>' + have + '</b>/' + bdcExpect) : '') + '</div>';
    piRenderBdcChecklist('pi-bdc-expect-list', items);
    piRenderBdcChecklist('pi-bdc-checklist', items);
  }).catch(function () {
    piRenderBdcChecklist('pi-bdc-expect-list');
    piRenderBdcChecklist('pi-bdc-checklist');
  });
};

