function piAirCode(b) {
  return String((b && (b.reservationId || b.reservation_id || b.confirmationCode || b.code)) || '').trim().toUpperCase();
}
function piAirExpectList(month) {
  var bks = (typeof S !== 'undefined' && Array.isArray(S.bks)) ? S.bks : [];
  var inv = [], credit = [], missing = [];
  bks.forEach(function (b) {
    if (piChan(b) !== 'airbnb') return;
    var createdYm = piYmFromTs(b.createdOnChannel != null ? b.createdOnChannel : b.created);
    var cancelYm = piYmFromTs(b.cancelledAt);
    var code = piAirCode(b);
    var row = {
      code: code,
      aptId: String(b.aptId || '').trim(),
      aptName: String(b.aptName || '').trim(),
      guestName: String(b.guestName || '').trim(),
      hosthubId: String(b.id || '').trim()
    };
    if (createdYm === month) {
      if (code) inv.push(Object.assign({}, row, { kind: 'invoice' }));
      else missing.push(Object.assign({}, row, { kind: 'invoice' }));
    }
    if (b.cancelled && cancelYm === month) {
      if (code) credit.push(Object.assign({}, row, { kind: 'credit_note' }));
      else missing.push(Object.assign({}, row, { kind: 'credit_note' }));
    }
  });
  return { inv: inv, credit: credit, missing: missing };
}
function piVaultHasAirCode(items, code, kind) {
  var c = String(code || '').toLowerCase();
  if (!c) return false;
  return (items || []).some(function (f) {
    if (String(f.channel || '').toLowerCase() !== 'airbnb') return false;
    var blob = (String(f.partner || '') + ' ' + String(f.filename || f.name || '')).toLowerCase();
    if (blob.indexOf(c.toLowerCase()) < 0) return false;
    if (kind === 'credit_note') return /credit/.test(blob) || String(f.partner || '').toLowerCase() === 'credit_note';
    return !/credit/.test(blob);
  });
}
function piRenderAirChecklist(targetId, items) {
  var el = document.getElementById(targetId);
  if (!el) return;
  var h = PI.health || {};
  var inv = h.airInvList || [];
  var credit = h.airCreditList || [];
  var missing = h.airMissing || [];
  if (!inv.length && !credit.length && !missing.length) {
    el.innerHTML = '<div style="color:var(--tx3)">No Airbnb documents expected for this month (or Hosthub not synced).</div>';
    return;
  }
  function row(x, kind) {
    var have = piVaultHasAirCode(items, x.code, kind);
    var mark = have ? '<span style="color:var(--tx-ok,#059669)">✓</span>' : '<span style="color:var(--tx-err,#b91c1c)">○</span>';
    var code = x.code || '<span style="color:var(--tx-err,#b91c1c)">missing code — re-sync Hosthub</span>';
    var label = (x.aptName || x.aptId || 'Apartment') + (x.guestName ? (' · ' + x.guestName) : '');
    return '<div>' + mark + ' <code>' + code + '</code> · ' + (kind === 'credit_note' ? 'credit note' : 'VAT invoice') +
      ' · ' + label + '</div>';
  }
  var haveInv = inv.filter(function (x) { return piVaultHasAirCode(items, x.code, 'invoice'); }).length;
  var haveCr = credit.filter(function (x) { return piVaultHasAirCode(items, x.code, 'credit_note'); }).length;
  el.innerHTML =
    '<div style="font-weight:600;margin-bottom:6px">Airbnb (Hosthub codes): invoices <b>' + haveInv + '</b>/' + inv.length +
    ' · credit notes <b>' + haveCr + '</b>/' + credit.length +
    (missing.length ? (' · <span style="color:var(--tx-err,#b91c1c)">' + missing.length + ' without reservationId</span>') : '') +
    '</div>' +
    '<div style="display:flex;flex-direction:column;gap:3px;max-height:220px;overflow:auto">' +
    inv.map(function (x) { return row(x, 'invoice'); }).join('') +
    credit.map(function (x) { return row(x, 'credit_note'); }).join('') +
    missing.map(function (x) { return row(x, x.kind); }).join('') +
    '</div>';
}
