window.piPull = async function () {
  var month = monthVal();
  var btn = document.getElementById('pi-pull-btn');
  if (btn) btn.disabled = true;
  msg('Pulling from portals (can take several minutes)…', true);
  try {
    var apts = ((PI.health && PI.health.bdcApts) || []).map(function (a) {
      return { aptId: a.aptId || '', aptName: a.aptName || '' };
    });
    if (!apts.length && typeof S !== 'undefined' && Array.isArray(S.apts)) {
      apts = S.apts.map(function (a) { return { aptId: a.id || a.aptId || '', aptName: a.name || a.aptName || '' }; });
    }
    var res = await fetch('/api/platform-invoices/pull', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ month: month, channel: 'all', apartments: apts })
    });
    var r = await res.json();
    var errTxt = (r.errors || []).map(function (e) {
      return (e.channel ? (e.channel + ': ') : '') + (e.property ? (e.property + ' — ') : '') + (e.error || e.hint || '');
    }).filter(Boolean).slice(0, 4).join(' · ');
    if (!res.ok) throw new Error((r.error || 'pull failed') + (r.hint ? (' — ' + r.hint) : '') + (errTxt ? (' · ' + errTxt) : ''));
    var n = (r.saved || []).length;
    if (n === 0) {
      msg('Automated pull saved 0 PDFs' + (errTxt ? (' — ' + errTxt) : '') +
        ' — Connect Airbnb/Booking session if login was blocked, then Pull again', false);
    } else {
      msg('Pulled ' + n + ' PDF(s) automatically' + (errTxt ? (' · notes: ' + errTxt) : ''), true);
    }
    await piHealth();
    await piReload();
  } catch (e) { msg(e.message || String(e), false); }
  finally { if (btn) btn.disabled = false; }
};

