window.piPull = async function () {
  var month = monthVal();
  var btn = document.getElementById('pi-pull-btn');
  if (btn) btn.disabled = true;
  msg('Pulling Airbnb VAT docs from Hosthub codes (can take several minutes)…', true);
  try {
    if (!PI.health || !PI.health.airInvList) await piHealth();
    var h = PI.health || {};
    var airbnbReservations = []
      .concat(h.airInvList || [])
      .concat(h.airCreditList || [])
      .map(function (x) {
        return {
          code: x.code,
          kind: x.kind || 'invoice',
          aptId: x.aptId || '',
          aptName: x.aptName || '',
          guestName: x.guestName || ''
        };
      })
      .filter(function (x) { return !!x.code; });
    if (!airbnbReservations.length) {
      msg('No Hosthub Airbnb reservation codes for ' + month + ' — sync Hosthub (need reservationId), then refresh Expect', false);
      return;
    }
    var apts = (typeof S !== 'undefined' && Array.isArray(S.apts))
      ? S.apts.map(function (a) { return { aptId: a.id || a.aptId || '', aptName: a.name || a.aptName || '' }; })
      : [];
    var res = await fetch('/api/platform-invoices/pull', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ month: month, channel: 'airbnb', apartments: apts, airbnbReservations: airbnbReservations })
    });
    var r = await res.json();
    var errTxt = (r.errors || []).map(function (e) {
      return (e.channel ? (e.channel + ': ') : '') + (e.code ? (e.code + ' — ') : '') + (e.error || e.hint || '');
    }).filter(Boolean).slice(0, 4).join(' · ');
    if (!res.ok) throw new Error((r.error || 'pull failed') + (r.hint ? (' — ' + r.hint) : '') + (errTxt ? (' · ' + errTxt) : ''));
    var n = (r.saved || []).length;
    if (n === 0) {
      msg('Airbnb pull saved 0 PDFs from ' + airbnbReservations.length + ' Hosthub code(s)' +
        (errTxt ? (' — ' + errTxt) : '') +
        ' — Connect Airbnb if login was blocked, then Pull again', false);
    } else {
      msg('Pulled ' + n + ' Airbnb PDF(s) from ' + (r.airbnbCodes || airbnbReservations.length) + ' Hosthub code(s)' +
        (errTxt ? (' · notes: ' + errTxt) : ''), true);
    }
    await piHealth();
    await piReload();
  } catch (e) { msg(e.message || String(e), false); }
  finally { if (btn) btn.disabled = false; }
};

